<script setup>
import {ref,computed} from 'vue'
import {api} from '../lib/api'
const props=defineProps({initial:Object,catalog:{type:Array,default:()=>[]}}),emit=defineEmits(['saved','cancel'])
function blank(type='multiple'){return {key:crypto.randomUUID(),title:'',prompt:'',type,options:[0,1,2,3].map(i=>({id:'choice-'+i,text:''})),correctOptionId:'choice-0',acceptedText:'',explanation:''}}
const subject=ref(props.initial?.subject??'vue'),unit=ref(props.initial?.unit??0),published=ref(props.initial?.published??true),reviewed=ref(false),busy=ref(false),error=ref(''),questions=ref(props.initial?[{...blank(props.initial.type),...props.initial,key:crypto.randomUUID(),acceptedText:props.initial.acceptedAnswers?.join(' | ')??''}]:[blank()]);let requestKey=crypto.randomUUID(),lastPayload=''
const units=computed(()=>props.catalog.find(s=>s.id===subject.value)?.units??[])
function add(type){if(busy.value||questions.value.length>=20)return;questions.value.push(blank(type))}
function remove(index){if(!busy.value&&questions.value.length>1)questions.value.splice(index,1)}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const data=questions.value.map(q=>({subject:subject.value,unit:unit.value,title:q.title,prompt:q.prompt,type:q.type,options:q.options,correctOptionId:q.correctOptionId,acceptedAnswers:q.acceptedText.split('|').map(a=>a.trim()).filter(Boolean),explanation:q.explanation,published:published.value,reviewed:reviewed.value}));let result;if(props.initial)result={items:[await api('/workshop/'+props.initial.postId,{method:'PUT',body:{...data[0],baseVersion:props.initial.version}})]};else{const snapshot=JSON.stringify(data);if(lastPayload&&lastPayload!==snapshot)requestKey=crypto.randomUUID();lastPayload=snapshot;result=await api('/workshop/batch',{method:'POST',body:{questions:data,requestKey}})}emit('saved',result.items)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="panel manual-editor"><div class="workshop-heading"><div><h2>{{initial?'문제 수정 · 새 버전':'직접 문제 만들기'}}</h2><p>유형을 선택해 문제를 추가하고 정답과 해설을 입력하세요.</p></div><b>{{questions.length}} / 20문제</b></div><form @submit.prevent="save"><fieldset :disabled="busy" class="manual-common"><legend>공통 설정</legend><label>과목<select v-model="subject"><option v-for="s in catalog" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>단원<select v-model.number="unit"><option :value="0">미정</option><option v-for="u in units" :key="u.number" :value="u.number" :disabled="u.locked">{{u.locked?'🔒 ':''}}{{u.title}}</option></select></label><p>‘미정’ 문제는 공식 진도율에 포함되지 않습니다. 단원이 지정된 문제는 공개된 진도에서만 풀 수 있어요.</p></fieldset><article v-for="(q,index) in questions" :key="q.key" class="manual-question"><div class="manual-question-heading"><h3>문제 {{index+1}} <span>{{q.type==='multiple'?'객관식':'주관식'}}</span></h3><button v-if="!initial&&questions.length>1" type="button" class="text-button" :disabled="busy" :aria-label="'문제 '+(index+1)+' 삭제'" @click="remove(index)">삭제 ✕</button></div><fieldset class="workshop-form manual-fields" :disabled="busy"><label>문제 유형<select v-model="q.type"><option value="multiple">객관식</option><option value="short">주관식</option></select></label><label>문제 제목<input v-model="q.title" required maxlength="100" placeholder="목록에 표시할 제목"/></label><label>문제 내용<textarea v-model="q.prompt" required maxlength="1500" rows="3"/></label><fieldset v-if="q.type==='multiple'"><legend>선택지 4개 · 정답 하나를 선택하세요</legend><label v-for="(o,i) in q.options" :key="i" class="editor-choice"><input v-model="q.correctOptionId" type="radio" :value="'choice-'+i" :name="q.key+'-answer'" :aria-label="'문제 '+(index+1)+' 정답 '+(i+1)"/><span>{{i+1}}</span><input v-model="o.text" required maxlength="300" :aria-label="'선택지 '+(i+1)"/></label></fieldset><label v-else>허용 정답 (여러 개는 |로 구분)<input v-model="q.acceptedText" required maxlength="2000" placeholder="예: ref | Vue ref"/><small>앞뒤 공백과 영문 대소문자는 무시하고 채점합니다.</small></label><label>해설<textarea v-model="q.explanation" required maxlength="3000" rows="3"/></label></fieldset></article><div v-if="!initial" class="manual-add-bar"><button type="button" class="light" :disabled="busy||questions.length>=20" @click="add('multiple')">＋ 객관식 추가</button><button type="button" class="light" :disabled="busy||questions.length>=20" @click="add('short')">＋ 주관식 추가</button><span>한 번에 최대 20문제</span></div><div class="manual-save-bar"><label class="check-line"><input v-model="published" type="checkbox" :disabled="busy"/>학생들에게 공유하기</label><label class="check-line"><input v-model="reviewed" type="checkbox" :disabled="busy"/>문제·정답·해설을 직접 검토했습니다.</label><p v-if="error" class="notice" role="alert">{{error}}</p><div class="toolbar"><button :disabled="busy||(published&&!reviewed)">{{busy?'저장 중…':initial?'새 버전 저장':'문제 '+questions.length+'개 저장'}}</button><button type="button" class="light" :disabled="busy" @click="emit('cancel')">취소</button></div></div></form></section></template>
